import { SettingsService } from './settings.service.js';
import { BadRequestException } from '@nestjs/common';

// Exercise the real cloudIAM validation against the local AWS emulator.
describe('scraper role validation on settings update', () => {
    let service: SettingsService;
    let loadPoints: jest.Mock;

    const businessID = 'biz-1';
    const subject = 'sub-1';

    beforeEach(() => {
        loadPoints = jest.fn().mockResolvedValue(undefined);
        const influx: any = { loadPoints, getLatestSettings: jest.fn().mockResolvedValue([]) };
        const scheduler: any = {};
        const env: any = {};
        service = new SettingsService(influx, scheduler, env);
        // Return an existing setting with no connection so build works without hitting influx/stripe.
        jest.spyOn(service, 'findAll').mockResolvedValue([{ businessID, cloudIAM: {} } as any]);
        jest.spyOn(SettingsService as any, 'logger', 'get').mockReturnValue({ log() {}, debug() {}, error() {}, warn() {} });
    });

    const run = (cloudIAM: any) =>
        service.update({ businessID, subject, cloudIAM } as any);

    it('valid role + correct externalId + ec2 read → saved', async () => {
        const res = await run({ iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-usage-scraper', externalId: 'nw-7f31c2' });
        expect(loadPoints).toHaveBeenCalledTimes(1);
        expect(res.message).toContain('updated');
    });

    it('open role (no externalId condition) + ec2 read → saved', async () => {
        const res = await run({ iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-open-scraper' });
        expect(loadPoints).toHaveBeenCalledTimes(1);
        expect(res.message).toContain('updated');
    });

    it('staging role correct externalId → saved', async () => {
        await run({ iamRoleArn: 'arn:aws:iam::300000000022:role/meteringco-staging-scraper', externalId: 'nw-stg-4410' });
        expect(loadPoints).toHaveBeenCalledTimes(1);
    });

    const badCases: Array<[string, any]> = [
        ['wrong externalId', { iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-usage-scraper', externalId: 'nope' }],
        ['missing externalId when required', { iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-usage-scraper' }],
        ['assumable but cannot read ec2 (reports-reader)', { iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-reports-reader', externalId: 'nw-a01b' }],
        ['assumable but cannot read ec2 (spend-reader)', { iamRoleArn: 'arn:aws:iam::300000000011:role/meteringco-spend-reader' }],
        ['assumable but no perms (bare-role)', { iamRoleArn: 'arn:aws:iam::300000000022:role/meteringco-bare-role' }],
        ['not trusted principal (deployment-pipeline)', { iamRoleArn: 'arn:aws:iam::300000000011:role/deployment-pipeline' }],
        ['service principal role', { iamRoleArn: 'arn:aws:iam::300000000022:role/ec2-instance-profile' }],
        ['nonexistent role', { iamRoleArn: 'arn:aws:iam::300000000011:role/nope' }],
    ];

    it.each(badCases)('bad request & nothing written: %s', async (_label, cloudIAM) => {
        await expect(run(cloudIAM)).rejects.toBeInstanceOf(BadRequestException);
        expect(loadPoints).not.toHaveBeenCalled();
    });

    it('blank role disconnects and clears externalId', async () => {
        const res = await run({ iamRoleArn: '', externalId: 'nw-7f31c2' });
        expect(loadPoints).toHaveBeenCalledTimes(1);
        const arg = (loadPoints.mock.calls[0][2] as any[])[0];
        // The stored cloudIAM tag should have empty role and empty external id.
        const tags = JSON.stringify(arg);
        expect(tags).toContain('"iamRoleArn":""');
        expect(tags).toContain('"externalId":""');
        expect(tags).not.toContain('nw-7f31c2');
        expect(res.message).toContain('updated');
    });

    it('cloudIAM present but names no role → bad request (not disconnect)', async () => {
        await expect(run({ externalId: 'nw-7f31c2' })).rejects.toBeInstanceOf(BadRequestException);
        expect(loadPoints).not.toHaveBeenCalled();
    });

    it('no cloudIAM in payload → unrelated update still saves', async () => {
        const res = await service.update({ businessID, subject, logoUrl: 'http://x/y.png' } as any);
        expect(loadPoints).toHaveBeenCalledTimes(1);
        expect(res.message).toContain('updated');
    });
});
