     * - A settings block that supplies cloudIAM but names no role (missing iamRoleArn) is a
     *   bad request, not a disconnect.
     * - A blank role means the customer is disconnecting; the external id is cleared as well.
     * - Otherwise the role must be assumable with the supplied external id AND the returned
     *   credentials must be able to read the instance inventory used by collection. Failure of
     *   either check is a bad request and, because this runs before any write, nothing is saved.
     */
    private async verifyScraperRole(updatedFields: Partial<UpdateSettingsDto>): Promise<void> {
        if (!('cloudIAM' in updatedFields)) {
            return;
        }
        const cloudIAM = updatedFields.cloudIAM as CloudIAM | undefined;
        // A cloudIAM block that names no role at all is invalid rather than a disconnect.
        if (!cloudIAM || cloudIAM.iamRoleArn === undefined || cloudIAM.iamRoleArn === null) {
            throw new BadRequestException('cloudIAM must specify an iamRoleArn');
        }
        const iamRoleArn = typeof cloudIAM.iamRoleArn === 'string' ? cloudIAM.iamRoleArn.trim() : cloudIAM.iamRoleArn;
        // A blank role means disconnect: clear the role and the external id.
        if (iamRoleArn === '') {
            const disconnected = new CloudIAM();
            disconnected.iamRoleArn = '';
            disconnected.externalId = '';
            updatedFields.cloudIAM = disconnected;
            return;
        }
        const externalId = cloudIAM.externalId ? cloudIAM.externalId : undefined;
        let credentials;
        try {
            credentials = fromTemporaryCredentials({
                params: { RoleArn: iamRoleArn, ExternalId: externalId },
                clientConfig: { region: 'us-east-1' },
            });
        } catch (e) {
            SettingsService.logger.error(`Unable to build assume-role provider for ${iamRoleArn}: ${e}`);
            throw new BadRequestException('Invalid IAM role or external ID');
        }
        // Reading the instance inventory forces the role to be assumed with the supplied external
        // id and proves the returned credentials can read the inventory collection relies on.
        // getInstanceWithFilters throws BadRequestException on any failure.
        await getInstanceWithFilters('us-east-1', credentials, []);
        // Persist the normalised role/external id.
        const normalised = new CloudIAM();
        normalised.iamRoleArn = iamRoleArn;
        normalised.externalId = externalId ?? '';
        updatedFields.cloudIAM = normalised;
    }

    async fileUpload({ file, businessID }: FileUploadDto): Promise<BasicResponseDTO> {
        const invoiceImageBucket = `meteringco-${process.env.STAGE}-brand-images`;
        const uuid = randomUUID();
        const imageKey = `${businessID}-invoice-image-${uuid}`;
        await putDocument(file, invoiceImageBucket, imageKey).done();
        this.update({
            businessID,
            logoUrl: `https://meteringco-${process.env.STAGE}-brand-images.s3.amazonaws.com/${businessID}-invoice-image-${uuid}`,
        });

        return { message: 'File uploaded successfully' };
    }
